shaders.literal:
#version 300 es
precision highp float;
precision highp int;
uniform int lookup;
out vec4 fragColor;
void main() {
  float values[3];
  values[0] = 0.125;
  values[1] = 0.5;
  values[2] = 0.875;
  fragColor = vec4(values[lookup], 0.0, 0.0, 1.0);
}

